apiVersion: argoproj.io/v1alpha1
kind: AnalysisTemplate
metadata:
  name: payments-smoke-check
spec:
  metrics:
    - nam
e: readiness-gate
      interval: 10s
      successCondition: result.ready == true
      failureLimit: 2
      provider:
        web:
          url: http://payments-api-preview/deployment/ready
          jsonPath: "{$.ready}"
```

